-- The schema TestSyncDatabase syncs on every pinned server, PostgreSQL 12 and
-- later, and that the parity harness syncs with Bytebase's driver. It covers
-- each object kind the sync reads, in the forms that change how it is read.

CREATE ROLE corpus_owner NOLOGIN;
CREATE ROLE corpus_reader LOGIN CREATEDB CONNECTION LIMIT 5 VALID UNTIL '2030-01-01 00:00:00+00';

CREATE EXTENSION hstore;
CREATE EXTENSION citext WITH SCHEMA public;
CREATE EXTENSION btree_gist;
CREATE EXTENSION postgres_fdw;
COMMENT ON EXTENSION hstore IS 'key/value pairs';

CREATE SCHEMA app AUTHORIZATION corpus_owner;
COMMENT ON SCHEMA app IS 'the application';
CREATE SCHEMA "Mixed Case";
CREATE SCHEMA audit;

-- Types.
CREATE TYPE app.mood AS ENUM ('happy', 'sad', 'it''s complicated');
COMMENT ON TYPE app.mood IS 'how it feels';
CREATE TYPE public.size AS ENUM ();
CREATE TYPE app.address AS (street text COLLATE "C", city varchar(50), zip int);
COMMENT ON TYPE app.address IS 'postal address';
COMMENT ON COLUMN app.address.street IS 'street line';
CREATE TYPE app.addresses AS (home app.address, others app.address[]);
CREATE TYPE app.empty_type AS ();
CREATE DOMAIN app.positive_int AS integer NOT NULL CHECK (VALUE > 0);
CREATE DOMAIN app.email AS citext CHECK (VALUE ~ '@');
CREATE TYPE app.float_range AS RANGE (subtype = float8); -- not restorable: TestDumpGaps
CREATE COLLATION app.ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false); -- not restorable: TestDumpGaps

-- Sequences.
CREATE SEQUENCE app.counter AS integer INCREMENT BY 5 MINVALUE -100 MAXVALUE 1000 START WITH 10 CACHE 3 CYCLE;
COMMENT ON SEQUENCE app.counter IS 'counts by five';
CREATE SEQUENCE app.owned_seq;
CREATE SEQUENCE audit.big_seq AS bigint;

-- Functions and procedures.
CREATE FUNCTION app.add(a integer, b integer DEFAULT 1) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT a + b $$;
CREATE FUNCTION app.add(a numeric, b numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE AS $$ SELECT a + b $$;
COMMENT ON FUNCTION app.add(integer, integer) IS 'adds integers';
CREATE FUNCTION app.touch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END
$$;
CREATE FUNCTION audit.on_ddl() RETURNS event_trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE NOTICE 'ddl: %', tg_tag;
END
$$;
CREATE PROCEDURE app.reset(n integer) LANGUAGE plpgsql AS $$
BEGIN
    PERFORM setval('app.counter', n);
END
$$;
CREATE FUNCTION app.items_named(p text) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path = app AS $$ SELECT p $$;

-- Tables.
CREATE TABLE app.customer (
    id bigint GENERATED ALWAYS AS IDENTITY (START WITH 100 INCREMENT BY 2) PRIMARY KEY,
    alt_id integer GENERATED BY DEFAULT AS IDENTITY,
    email app.email NOT NULL,
    name text COLLATE "C" NOT NULL DEFAULT 'anon',
    nick text COLLATE app.ci, -- not restorable: TestDumpGaps
    mood app.mood DEFAULT 'happy',
    home app.address,
    tags text[] DEFAULT '{}',
    matrix integer[][],
    attrs hstore,
    doc jsonb DEFAULT '{"a": [1, 2]}'::jsonb,
    balance numeric(12, 2) DEFAULT 0 CHECK (balance >= 0),
    ratio double precision,
    score real,
    small smallint,
    flag boolean DEFAULT true,
    ts timestamp(3) DEFAULT now(),
    tstz timestamptz,
    born date,
    alarm time(2) with time zone,
    span interval(1),
    bits bit(3),
    vbits varbit(8),
    ip inet,
    mac macaddr,
    pt point,
    words tsvector,
    uid uuid,
    raw bytea DEFAULT '\xdeadbeef',
    counter integer DEFAULT nextval('app.counter'),
    owned bigint DEFAULT nextval('app.owned_seq'),
    full_name text GENERATED ALWAYS AS (name || ' <' || email || '>') STORED,
    "Quoted Col" text,
    updated_at timestamptz,
    dropped text,
    CONSTRAINT customer_email_key UNIQUE (email),
    CONSTRAINT customer_name_check CHECK (length(name) > 0) NOT VALID
);
ALTER TABLE app.customer DROP COLUMN dropped;
ALTER SEQUENCE app.owned_seq OWNED BY app.customer.owned;
ALTER TABLE app.customer OWNER TO corpus_owner;
COMMENT ON TABLE app.customer IS 'who buys';
COMMENT ON COLUMN app.customer.email IS 'unique email';
COMMENT ON CONSTRAINT customer_email_key ON app.customer IS 'one account per email';
CREATE INDEX customer_lower_name ON app.customer (lower(name) DESC NULLS LAST);
CREATE INDEX customer_tags ON app.customer USING gin (tags);
CREATE INDEX customer_partial ON app.customer (mood, id) WHERE flag;
CREATE INDEX customer_include ON app.customer (alt_id) INCLUDE (name, mood);
CREATE INDEX customer_opclass ON app.customer (name text_pattern_ops, nick); -- not restorable: TestDumpGaps
CREATE INDEX customer_brin ON app.customer USING brin (ts) WITH (pages_per_range = 16);
COMMENT ON INDEX app.customer_partial IS 'happy flags';
CREATE TRIGGER customer_touch BEFORE UPDATE ON app.customer
    FOR EACH ROW WHEN (OLD.name IS DISTINCT FROM NEW.name) EXECUTE FUNCTION app.touch();
COMMENT ON TRIGGER customer_touch ON app.customer IS 'keeps updated_at';
ALTER TABLE app.customer ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_self ON app.customer USING (name = current_user);

CREATE TABLE app.orders (
    id bigserial,
    customer_id bigint NOT NULL,
    placed_on date NOT NULL,
    total numeric,
    PRIMARY KEY (id, placed_on),
    CONSTRAINT orders_customer_fk FOREIGN KEY (customer_id) REFERENCES app.customer (id)
        ON DELETE CASCADE ON UPDATE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE app.booking (
    room int,
    during tstzrange,
    CONSTRAINT booking_no_overlap EXCLUDE USING gist (room WITH =, during WITH &&)
);

CREATE TABLE app.ref_target (a int, b int, UNIQUE (a, b));
CREATE TABLE app.ref_source (
    x int, y int,
    FOREIGN KEY (x, y) REFERENCES app.ref_target (a, b) MATCH FULL ON DELETE SET DEFAULT
);

CREATE TABLE "Mixed Case"."Table" ("Id" int PRIMARY KEY, "Value" text);
CREATE TABLE public.plain (a serial, b text);
CREATE UNLOGGED TABLE audit.scratch (note text);

-- Inheritance.
CREATE TABLE app.animal (name text, legs int CHECK (legs >= 0));
CREATE TABLE app.dog (breed text) INHERITS (app.animal);

-- Partitions: range with a list subpartition, hash, list with a default,
-- indexes on the parent that each partition inherits.
CREATE TABLE app.measurement (
    city_id int NOT NULL,
    logdate date NOT NULL,
    region text NOT NULL,
    peak int CHECK (peak > -100)
) PARTITION BY RANGE (logdate);
CREATE TABLE app.measurement_2025 PARTITION OF app.measurement
    FOR VALUES FROM ('2025-01-01') TO ('2026-01-01') PARTITION BY LIST (region);
CREATE TABLE app.measurement_2025_eu PARTITION OF app.measurement_2025 FOR VALUES IN ('eu');
CREATE TABLE app.measurement_2025_other PARTITION OF app.measurement_2025 DEFAULT;
CREATE TABLE app.measurement_2026 PARTITION OF app.measurement
    FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE INDEX measurement_city ON app.measurement (city_id, logdate);
CREATE UNIQUE INDEX measurement_key ON app.measurement (city_id, logdate, region);
COMMENT ON TABLE app.measurement_2026 IS 'this year';

CREATE TABLE app.sharded (id int, v text) PARTITION BY HASH (id);
CREATE TABLE app.sharded_0 PARTITION OF app.sharded FOR VALUES WITH (MODULUS 2, REMAINDER 0);
CREATE TABLE app.sharded_1 PARTITION OF app.sharded FOR VALUES WITH (MODULUS 2, REMAINDER 1);

-- A partition's own name can be quoted and mixed case, its bounds can be
-- multi-column with MINVALUE and MAXVALUE, and a table created on its own can
-- be attached with a CHECK and an index of its own.
CREATE TABLE app."Own Measure" ("Id" int NOT NULL, "On" date NOT NULL) PARTITION BY RANGE ("On");
CREATE TABLE app."Own Measure 2025" PARTITION OF app."Own Measure" FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
CREATE INDEX own_measure_id ON app."Own Measure" ("Id");
CREATE TABLE app.multi_bound (a int NOT NULL, b int NOT NULL) PARTITION BY RANGE (a, b);
CREATE TABLE app.multi_bound_low PARTITION OF app.multi_bound FOR VALUES FROM (MINVALUE, MINVALUE) TO (10, MAXVALUE);
CREATE TABLE app.multi_bound_high PARTITION OF app.multi_bound FOR VALUES FROM (10, MAXVALUE) TO (MAXVALUE, MAXVALUE);
CREATE TABLE app.attached (id int NOT NULL, v text) PARTITION BY LIST (v);
CREATE TABLE app.attached_x (id int NOT NULL, v text NOT NULL, CONSTRAINT attached_x_positive CHECK (id > 0));
ALTER TABLE app.attached ATTACH PARTITION app.attached_x FOR VALUES IN ('x');
CREATE INDEX attached_x_id ON app.attached_x (id);

-- Views, dependencies, rules, triggers on views.
CREATE VIEW app.happy_customer AS
    SELECT c.id, c.name, o.total FROM app.customer c JOIN app.orders o ON o.customer_id = c.id
    WHERE c.mood = 'happy';
COMMENT ON VIEW app.happy_customer IS 'happy ones';
CREATE VIEW app.customer_names AS SELECT id, name FROM app.customer WITH CHECK OPTION;
CREATE FUNCTION app.names_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RETURN NEW;
END
$$;
CREATE TRIGGER names_insert INSTEAD OF INSERT ON app.customer_names
    FOR EACH ROW EXECUTE FUNCTION app.names_insert();
CREATE VIEW app.view_on_view AS SELECT name FROM app.happy_customer;
CREATE RULE plain_log AS ON INSERT TO public.plain WHERE NEW.b IS NOT NULL
    DO ALSO INSERT INTO audit.scratch VALUES (NEW.b);
CREATE RULE plain_nothing AS ON DELETE TO public.plain DO INSTEAD NOTHING;
CREATE FUNCTION app.customer_count() RETURNS bigint LANGUAGE sql STABLE
    AS 'SELECT count(*) FROM app.customer';

-- Materialized views.
CREATE MATERIALIZED VIEW app.order_totals AS
    SELECT customer_id, sum(total) AS total FROM app.orders GROUP BY customer_id
    WITH NO DATA;
CREATE UNIQUE INDEX order_totals_customer ON app.order_totals (customer_id);
COMMENT ON MATERIALIZED VIEW app.order_totals IS 'per customer';

-- Foreign tables.
CREATE SERVER loopback FOREIGN DATA WRAPPER postgres_fdw OPTIONS (host 'localhost', dbname 'postgres'); -- not restorable: TestDumpGaps
CREATE FOREIGN TABLE audit.remote_orders (id int NOT NULL, note varchar(30)) -- not restorable: TestDumpGaps
    SERVER loopback OPTIONS (schema_name 'public', table_name 'orders'); -- not restorable: TestDumpGaps

-- Shapes Bytebase's sync got wrong before the move: a sequence owned by a
-- column after a dropped one, a view of a relation it reads no column of, a
-- name with an apostrophe, an array of a user type.
CREATE TABLE app.seq_owner (removed text, id serial, payload text);
ALTER TABLE app.seq_owner DROP COLUMN removed;
CREATE TABLE public.z_source (v int);
CREATE VIEW public.a_count AS SELECT count(*) AS n FROM public.z_source;
CREATE VIEW app."owner's view" AS SELECT id FROM app.customer;
ALTER TABLE app.customer ADD COLUMN moods app.mood[];

-- Event triggers.
CREATE EVENT TRIGGER corpus_ddl ON ddl_command_end WHEN TAG IN ('CREATE TABLE', 'ALTER TABLE')
    EXECUTE FUNCTION audit.on_ddl();
COMMENT ON EVENT TRIGGER corpus_ddl IS 'logs DDL';
CREATE EVENT TRIGGER corpus_drop ON sql_drop EXECUTE FUNCTION audit.on_ddl();
ALTER EVENT TRIGGER corpus_drop DISABLE;

-- Objects sync does not read, which must not disturb what it does.
CREATE PUBLICATION corpus_pub FOR TABLE app.orders;
CREATE STATISTICS app.customer_stats (dependencies) ON mood, flag FROM app.customer;
GRANT SELECT ON app.customer TO corpus_reader;
